WITH row AS (INSERT INTO zc_private.discord_digest(guild_id,channel_id,daily_enabled, weekly_enabled,delivery_hour,weekly_day,next_delivery_at) VALUES($1,$2,$3,$4,$5,$6,$7::timestamptz) ON CONFLICT(guild_id) DO UPDATE SET channel_id=excluded.channel_id,daily_enabled=excluded.daily_enabled, weekly_enabled=excluded.weekly_enabled,delivery_hour=excluded.delivery_hour,weekly_day=excluded.weekly_day, next_delivery_at=excluded.next_delivery_at,date_updated=clock_timestamp() RETURNING *) SELECT jsonb_build_object('guildId',guild_id::text,'channelId',channel_id::text,'dailyEnabled',daily_enabled, 'weeklyEnabled',weekly_enabled,'deliveryHour',delivery_hour,'weeklyDay',weekly_day,'nextDeliveryAt', CASE WHEN next_delivery_at IS NULL THEN NULL ELSE to_jsonb(to_char(next_delivery_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) END,'leaseUntil',CASE WHEN lease_until IS NULL THEN NULL ELSE to_jsonb(to_char(lease_until AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) END,'dateUpdated', to_char(date_updated AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS value FROM row
